class Solution {
public:
    vector<int> findNumOfValidWords(vector<string>& words, vector<string>& puzzles) {
        unordered_map<int,int> cnt;
        cnt.reserve(words.size() * 2);
        for (const string& w : words) {
            int m = 0;
            for (char c : w) m |= 1 << (c - 'a');
            cnt[m]++;
        }
        vector<int> res;
        res.reserve(puzzles.size());
        for (const string& p : puzzles) {
            int pmask = 0;
            for (char c : p) pmask |= 1 << (c - 'a');
            int first = 1 << (p[0] - 'a');
            int total = 0;
            int sub = pmask;
            while (true) {
                if (sub & first) {
                    auto it = cnt.find(sub);
                    if (it != cnt.end()) total += it->second;
                }
                if (sub == 0) break;
                sub = (sub - 1) & pmask;
            }
            res.push_back(total);
        }
        return res;
    }
};
